/**
 * LihForge Studio Plugin Bridge Protocol
 *
 * Prepared for Phase 4:
 * Localhost HTTP / WebSocket bridge connecting LihForge Desktop to Roblox Studio.
 * Enforces:
 * 1. Random pairing token generated by LihForge
 * 2. Strict loopback binding (127.0.0.1)
 * 3. Schema validation for all remote instance manipulation
 */

export interface StudioConnectionStatus {
  connected: boolean;
  port: number;
  pairingToken: string;
  studioPlaceName?: string;
  lastPingTimestamp?: number;
}
